/*
  pdf.js
  Görev: reports.js ile uyumlu Türkçe karakter destekli PDF üretimi.
  Not: pdfMake + Roboto VFS Türkçe karakterleri destekler.
*/
import { state } from "./state.js";
import { money, dateTR } from "./format.js";

const REPORT_HEADER_IMAGE = "data:image/png;base64,";

function safe(value) {
  return String(value ?? "")
    .replace(/[\u0000-\u001F]/g, "")
    .trim();
}

function fileSafe(name) {
  return safe(name).replace(/[\\/:*?"<>|]/g, "_") || "rapor";
}

function strictReportDealerShare(report) {
  const rows = Array.isArray(report?.rows) ? report.rows : [];
  return rows.reduce((sum, row) => {
    const value = Number(row?.reportDealerShare);
    return sum + (Number.isFinite(value) ? value : 0);
  }, 0);
}

function tableHeaderCell(text, alignment = "left") {
  return {
    text: safe(text),
    style: "tableHeader",
    fillColor: "#eef8e5",
    alignment,
    noWrap: true,
    fontSize: 7.8,
    margin: [0, 1, 0, 1]
  };
}

function tableTextCell(text, options = {}) {
  return {
    text: safe(text),
    alignment: options.alignment || "left",
    noWrap: options.noWrap ?? false,
    fontSize: options.fontSize || 8.2,
    lineHeight: options.lineHeight || 1.12,
    margin: options.margin || [0, 1, 0, 1]
  };
}

const DEALER_CUSTOMER_FIRM_TEXT_WIDTH = 220;
let pdfMeasureCanvas = null;

function measurePdfTextWidth(text, fontSize = 8.2) {
  const value = String(text || "");

  try {
    if (!pdfMeasureCanvas && typeof document !== "undefined") {
      pdfMeasureCanvas = document.createElement("canvas");
    }

    const context = pdfMeasureCanvas?.getContext?.("2d");
    if (context) {
      const pointToPixel = 96 / 72;
      context.font = `${fontSize * pointToPixel}px Roboto, Arial, sans-serif`;
      return context.measureText(value).width / pointToPixel;
    }
  } catch {
    // Canvas ölçümü alınamazsa güvenli yaklaşık hesaba düş.
  }

  return value.length * fontSize * 0.62;
}

function fitDealerCustomerFirmText(text, maxWidth = DEALER_CUSTOMER_FIRM_TEXT_WIDTH, fontSize = 8.2) {
  const value = safe(text).replace(/\s+/g, " ").trim();
  const ellipsis = "...";

  if (!value || measurePdfTextWidth(value, fontSize) <= maxWidth) return value;

  let low = 0;
  let high = value.length;
  let best = ellipsis;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const candidate = `${value.slice(0, mid).trimEnd()}${ellipsis}`;

    if (measurePdfTextWidth(candidate, fontSize) <= maxWidth) {
      best = candidate;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return best;
}

function wrapGeneralReportChannelText(text) {
  const value = safe(text).replace(/\s+/g, " ").trim();
  if (!value) return "";

  // Çoklu kanal seçiminde "Kanal A / Kanal B" metni dar PDF hücresinde
  // yanındaki Bayi kutusuna taşmamalı. Slash ayracı korunur, her kanal
  // hücre içinde yeni satıra alınabilir.
  return value
    .split("/")
    .map(part => part.trim())
    .filter(Boolean)
    .map((part, index, parts) => index < parts.length - 1 ? `${part} /` : part)
    .join("\n");
}

function tableNumberCell(text, alignment = "right") {
  return {
    text: safe(text),
    alignment,
    noWrap: true,
    fontSize: 8,
    lineHeight: 1.08,
    margin: [0, 1, 0, 1]
  };
}


function ensurePdfMake() {
  if (!window.pdfMake) {
    alert("PDF kütüphanesi yüklenemedi. İnternet bağlantısını veya script yüklemesini kontrol edin.");
    throw new Error("pdfMake missing");
  }
}

function isMobilePdfShareContext() {
  try {
    const narrowScreen = window.matchMedia?.("(max-width: 767px)")?.matches;
    const coarsePointer = window.matchMedia?.("(hover: none) and (pointer: coarse)")?.matches;
    const standalone = window.matchMedia?.("(display-mode: standalone)")?.matches || window.navigator.standalone === true;
    return Boolean(narrowScreen || coarsePointer || standalone);
  } catch {
    return window.innerWidth <= 767;
  }
}

function createPdfBlob(pdf) {
  return new Promise(resolve => {
    pdf.getBlob(blob => resolve(blob));
  });
}

async function sharePdfFileOnly(pdf, filename) {
  if (!navigator.share || typeof File === "undefined") return false;

  const blob = await createPdfBlob(pdf);
  const file = new File([blob], filename, { type: "application/pdf" });
  const sharePayload = { files: [file] };

  if (navigator.canShare && !navigator.canShare(sharePayload)) return false;

  await navigator.share(sharePayload);
  return true;
}

async function outputPdf(docDefinition, filename, mode) {
  ensurePdfMake();

  const pdf = window.pdfMake.createPdf(docDefinition);

  if ((mode === "save" || mode === "share") && isMobilePdfShareContext()) {
    try {
      const shared = await sharePdfFileOnly(pdf, filename);
      if (shared) return;
    } catch (error) {
      if (error?.name === "AbortError") return;
      console.warn("PDF dosya paylaşımı başarısız, varsayılan PDF akışına dönülüyor:", error);
    }
  }

  if (mode === "save" || mode === "share") {
    pdf.download(filename);
    return;
  }

  pdf.open();
}

function commonHeader(title, subtitle = "") {
  return [];
}


function monthNameFromPeriodKey(periodKey) {
  const months = [
    "", "Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran",
    "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"
  ];

  const month = Number(String(periodKey || "").split("-")[1]);
  return months[month] || "";
}

function periodYearLabelFromPeriodKey(periodKey) {
  const keys = String(periodKey || "")
    .split(",")
    .map(value => value.trim())
    .filter(Boolean);

  if (!keys.length) return "";
  if (keys.length === 1) {
    const raw = keys[0];
    const [year] = raw.split("-");
    const monthName = monthNameFromPeriodKey(raw);
    if (year && monthName) return `${year} / ${monthName}`;
    return monthName || year || "";
  }

  const years = [...new Set(keys.map(key => key.split("-")[0]).filter(Boolean))];
  const monthNames = keys.map(monthNameFromPeriodKey).filter(Boolean);
  if (years.length === 1 && monthNames.length) return `${years[0]} / ${monthNames.join(", ")}`;
  return keys.map(key => periodYearLabelFromPeriodKey(key)).filter(Boolean).join(" / ");
}

