function baseDefinition(content) {
  return {
    pageSize: "A4",
    pageMargins: [40, 116, 40, 40],
    info: {
      title: "Dikesoft Rapor",
      author: "Dikesoft",
      subject: "Hesap Özeti"
    },
    defaultStyle: {
      font: "Roboto",
      fontSize: 9.5,
      color: "#172416"
    },
    styles: {
      brandTitle: { fontSize: 17, bold: true, color: "#17351a" },
      docTitle: { fontSize: 12.5, bold: true, color: "#7ed321" },
      sectionTitle: { fontSize: 11, bold: true, color: "#2d5a1b" },
      mutedSmall: { fontSize: 8.5, color: "#66785f" },
      tableHeader: { bold: true, fontSize: 9, color: "#17351a" },
      totalText: { bold: true, fontSize: 10, color: "#17351a" }
    },
    header: function(currentPage, pageCount) {
      return {
        image: REPORT_HEADER_IMAGE,
        width: 520,
        alignment: "center",
        margin: [0, 20, 0, 0]
      };
    },
    footer: function(currentPage, pageCount) {
      return {
        text: currentPage + " / " + pageCount,
        alignment: "right",
        margin: [0, 10, 19.84, 0],
        fontSize: 8,
        color: "#66785f"
      };
    },
    content
  };
}

export function createGeneralPdf(mode = "open") {
  const body = [
    [
      tableHeaderCell("Sıra", "center"),
      tableHeaderCell("Kanal"),
      tableHeaderCell("Bayi"),
      tableHeaderCell("KP", "right"),
      tableHeaderCell("BP", "right"),
      tableHeaderCell("Fatura Adet", "right"),
      tableHeaderCell("Toplam Fatura", "right"),
      tableHeaderCell("Kanal Payı", "right"),
      tableHeaderCell("Bayi Payı", "right")
    ],
    ...state.reports.map((r, i) => [
      tableNumberCell(String(i + 1), "center"),
      tableTextCell(wrapGeneralReportChannelText(r.kanal || r.dagitici || ""), { noWrap: false, fontSize: 7.8, lineHeight: 1.08, margin: [0, 1, 0, 1] }),
      tableTextCell(r.bayi, { noWrap: false, fontSize: 8.2, lineHeight: 1.12 }),
      tableNumberCell(String(r.kp ?? 0)),
      tableNumberCell(String(r.bp ?? 0)),
      tableNumberCell(String(r.invoiceCount ?? 0)),
      tableNumberCell(money(r.totalInvoice)),
      tableNumberCell(money(r.channelShare)),
      tableNumberCell(money(strictReportDealerShare(r)))
    ])
  ];

  const totalInvoice = state.reports.reduce((a, r) => a + Number(r.totalInvoice || 0), 0);
  const totalChannel = state.reports.reduce((a, r) => a + Number(r.channelShare || 0), 0);
  const totalDealer = state.reports.reduce((a, r) => a + strictReportDealerShare(r), 0);

  const doc = baseDefinition([
    ...commonHeader("GENEL ÖZET RAPORU", dateTR(new Date())),
    {
      table: {
        headerRows: 1,
        keepWithHeaderRows: 1,
        dontBreakRows: true,
        widths: [20, 64, "*", 22, 22, 48, 66, 56, 56],
        body
      },
      layout: {
        ...tableLayout(),
        paddingLeft: () => 4,
        paddingRight: () => 4,
        paddingTop: () => 4,
        paddingBottom: () => 4
      }
    },
    {
      columns: [
        { text: `Toplam Fatura: ${money(totalInvoice)}`, style: "totalText" },
        { text: `Kanal Payı: ${money(totalChannel)}`, style: "totalText", alignment: "center" },
        { text: `Bayi Payı: ${money(totalDealer)}`, style: "totalText", alignment: "right" }
      ],
      margin: [0, 16, 0, 0]
    }
  ]);

  return outputPdf(doc, "genel-ozet.pdf", mode);
}

function buildDealerPdfDefinition(report) {
  const rows = report.rows || [];

  const body = [
    [
      tableHeaderCell("Sıra", "center"),
      tableHeaderCell("Tarih"),
      tableHeaderCell("VKN/TCKN"),
      tableHeaderCell("Müşteri Firma"),
      tableHeaderCell("Fatura Tutar", "right"),
      tableHeaderCell("Bayi Payı", "right")
    ],
    ...rows.map((row, i) => {
      const tutar = Number(row.faturaTutari || 0);
      // Satır bazlı bayi payı calculator.js içinde DAGITICI/KANAL + BAYI
      // kesin eşleşmesiyle hesaplanır. Burada rapor geneli BP ile yeniden
      // hesaplama yapılmaz; aksi hâlde Tümü raporunda başka dağıtıcının oranı
      // satıra taşınabilir.
      const bayiPayi = Number.isFinite(Number(row.reportDealerShare))
        ? Number(row.reportDealerShare)
        : 0;
      return [
        tableNumberCell(String(i + 1), "center"),
        tableTextCell(dateTR(row.faturaTarihi || row.tarih), { noWrap: true, fontSize: 8 }),
        tableTextCell(row.vkn || row.vknTckn, { noWrap: true, fontSize: 8 }),
        tableTextCell(fitDealerCustomerFirmText(row.unvan || row.musteri), { noWrap: true, fontSize: 8.2, lineHeight: 1.12 }),
        tableNumberCell(money(tutar)),
        tableNumberCell(money(bayiPayi))
      ];
    })
  ];

  return baseDefinition([
    ...commonHeader("BAYİ HESAP ÖZETİ", safe(report.bayi)),
    ...reportIntro(report),
    {
      table: {
        headerRows: 1,
        keepWithHeaderRows: 1,
        dontBreakRows: true,
        widths: [18, 50, 60, "*", 58, 52],
        body
      },
      layout: {
        ...tableLayout(),
        paddingLeft: () => 4,
        paddingRight: () => 4,
        paddingTop: () => 4,
        paddingBottom: () => 4
      }
    },
    {
      columns: [
        { text: `Toplam Fatura: ${money(report.totalInvoice)}`, style: "totalText" },
        { text: `Bayi Payı: ${money(strictReportDealerShare(report))}`, style: "totalText", alignment: "right" }
      ],
      margin: [0, 16, 0, 0]
    },
    ...reportFooterBlock()
  ]);
}

export function createDealerPdf(report, mode = "open") {
  const doc = buildDealerPdfDefinition(report);
  return outputPdf(doc, `${fileSafe(report.bayi)}.pdf`, mode);
}

export function createDealerPdfBlob(report) {
  ensurePdfMake();

  return new Promise((resolve, reject) => {
    try {
      const doc = buildDealerPdfDefinition(report);
      const filename = `${fileSafe(report.bayi)}.pdf`;
      window.pdfMake.createPdf(doc).getBlob(blob => resolve({ blob, filename }));
    } catch (error) {
      reject(error);
    }
  });
}

export function createDealerPdfBase64(report) {
  ensurePdfMake();

  return new Promise((resolve, reject) => {
    try {
      const doc = buildDealerPdfDefinition(report);
      window.pdfMake.createPdf(doc).getBase64(base64 => resolve(base64));
    } catch (error) {
      reject(error);
    }
  });
}

function tableLayout() {
  return {
    hLineColor: () => "#d9e8d0",
    vLineColor: () => "#d9e8d0",
    fillColor: rowIndex => rowIndex > 0 && rowIndex % 2 === 0 ? "#fbfff7" : null,
    paddingTop: () => 6,
    paddingBottom: () => 6,
    paddingLeft: () => 5,
    paddingRight: () => 5
  };
}
